@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Count - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    min-width: 90px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ccc;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    min-width: 30px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="work-entry-editor">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check mb-2">
                <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                <label class="form-check-label" for="current-@Index">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;

    private async Task Update(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

.work-entry-editor {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h5 {
    margin: 0;
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="reference-editor">
    <div class="ref-header">
        <h5>Reference @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Name *</label>
            <input type="text" class="form-control" value="@Reference.Name"
                   @onchange="e => Update(Reference with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Relationship *</label>
            <input type="text" class="form-control" value="@Reference.Relationship"
                   @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" value="@Reference.Email"
                   @onchange="e => Update(Reference with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

.reference-editor {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.ref-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.ref-header h5 {
    margin: 0;
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Count - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    min-width: 90px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ccc;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    min-width: 30px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="work-entry-editor">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check mb-2">
                <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                <label class="form-check-label" for="current-@Index">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;

    private async Task Update(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

