arguments.file_text:
@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" value="@Model.FullName"
               @onchange="e => Model = Model with { FullName = (string?)e.Value ?? "" }" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" value="@Model.Email"
               @onchange="e => Model = Model with { Email = (string?)e.Value ?? "" }" />
        @if (emailInvalid)
        {
            <div class="invalid-feedback">Please enter a valid email address.</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" value="@Model.Phone"
               @onchange="e => Model = Model with { Phone = (string?)e.Value ?? "" }" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" rows="2" value="@Model.Address"
                  @onchange="e => Model = Model with { Address = (string?)e.Value ?? "" }"></textarea>
    </div>

    <div class="step-buttons">
        <div></div>
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo Model { get; set; } = new("", "", "", "");
    [Parameter] public EventCallback<PersonalInfo> ModelChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool emailInvalid;
    private bool isValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        emailInvalid = false;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                emailInvalid = true;
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        await ModelChanged.InvokeAsync(Model);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply
@using sv_19792aca6b7d47b6b47064fafb2a2096.Models

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="@Entries[index]"
                         Index="index"
                         CanRemove="@(Entries.Count > 1)"
                         OnEntryChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await EntriesChanged.InvokeAsync(Entries);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_19792aca6b7d47b6b47064fafb2a2096.Components.Pages.Apply
@using sv_19792aca6b7d47b6b47064fafb2a2096.Models

<div class="step-content">
    <h3>References</h3>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
